local DECALS = {
	{part=2113,texture="rbxassetid://1008743",transparency=0},
	{part=2118,texture="rbxassetid://1008744",transparency=0},
	{part=2123,texture="rbxassetid://1008745",transparency=0},
	{part=2128,texture="rbxassetid://1008748",transparency=0},
}

local function isStandardF3X(obj)
	if not obj or obj.Name ~= "Building Tools" then
		return false
	end
	local api = obj:FindFirstChild("SyncAPI")
	local endpoint = api and api:FindFirstChild("ServerEndpoint")
	return endpoint ~= nil and endpoint:IsA("RemoteFunction")
end

local function findStandardF3X()
	local character = player.Character
	if character then
		local direct = character:FindFirstChild("Building Tools")
		if isStandardF3X(direct) then
			return direct, direct.SyncAPI.ServerEndpoint
		end
	end

	local backpack = player:FindFirstChildOfClass("Backpack")
	if backpack then
		local direct = backpack:FindFirstChild("Building Tools")
		if isStandardF3X(direct) then
			return direct, direct.SyncAPI.ServerEndpoint
		end
	end

	if character then
		for _, obj in ipairs(character:GetDescendants()) do
			if isStandardF3X(obj) then
				return obj, obj.SyncAPI.ServerEndpoint
			end
		end
	end

	return nil, nil
end

local function makeCFrame(values)
	return CFrame.new(table.unpack(values))
end

local function main()
	local tool, endpoint = findStandardF3X()
	if not endpoint then
		warn('Standard "Building Tools" with SyncAPI.ServerEndpoint was not found in Character or Backpack. Equip the tool and run again.')
		return
	end

	local function f3x(action, ...)
		local args = table.pack(...)
		local ok, result = pcall(function()
			return endpoint:InvokeServer(action, table.unpack(args, 1, args.n))
		end)
		if not ok then
			warn(("F3X action %s failed: %s"):format(tostring(action), tostring(result)))
			return false, result
		end
		return true, result
	end

	local partLimit = #PARTS
	if CONFIG.maxParts > 0 then
		partLimit = math.min(partLimit, CONFIG.maxParts)
	end

	print(("F3X build starting: %d parts (of %d), %d models, %d decals"):format(partLimit, #PARTS, #MODELS, #DECALS))

	local created = {}
	local createdById = {}
	local partData = {}
	local byModel = {}
	local createFailures = 0
	local createWarnings = 0

	for i = 1, partLimit do
		local d = PARTS[i]
		local cf = makeCFrame(d.cf)
		local ok, part = f3x("CreatePart", "Normal", cf, workspace)

		if ok and typeof(part) == "Instance" and part:IsA("BasePart") then
			created[#created + 1] = part
			createdById[d.id] = part
			partData[part] = d
			local list = byModel[d.m]
			if not list then
				list = {}
				byModel[d.m] = list
			end
			list[#list + 1] = part
		else
			createFailures = createFailures + (1)
			createWarnings = createWarnings + (1)
			if createWarnings <= 10 then
				warn(("CreatePart failed for source part %d (%s): server returned %s"):format(d.id, d.n, tostring(part)))
			end
		end

		if i % 10 == 0 then
			task.wait(CONFIG.createDelay)
		end
		if i % 100 == 0 then
			print(("  created %d/%d"):format(i, partLimit))
		end
	end

	print(("CreatePart phase: %d created, %d failed"):format(#created, createFailures))
	if #created == 0 then
		warn("No parts were created. Check F3X building permissions and the allowed building area.")
		return
	end

	local function forEachChunk(list, fn)
		local i = 1
		while i <= #list do
			local j = math.min(i + CONFIG.chunkSize - 1, #list)
			fn(i, j)
			i = j + 1
			task.wait(CONFIG.chunkDelay)
		end
	end

	local resizeFailures, colorFailures, materialFailures = 0, 0, 0
	local anchorFailures, collisionFailures, nameFailures = 0, 0, 0

	-- Size + CFrame. SyncResize is enough; no separate SyncMove is needed for parts.
	forEachChunk(created, function(a, b)
		local changes = {}
		for k = a, b do
			local p = created[k]
			local d = partData[p]
			changes[#changes + 1] = {
				Part = p,
				CFrame = makeCFrame(d.cf),
				Size = Vector3.new(table.unpack(d.s)),
			}
		end
		local ok = f3x("SyncResize", changes)
		if not ok then
			resizeFailures = resizeFailures + ((b - a + 1))
		end
	end)

	forEachChunk(created, function(a, b)
		local changes = {}
		for k = a, b do
			local p = created[k]
			local d = partData[p]
			changes[#changes + 1] = {
				Part = p,
				Color = Color3.new(table.unpack(d.c)),
				UnionColoring = false,
			}
		end
		local ok = f3x("SyncColor", changes)
		if not ok then
			colorFailures = colorFailures + ((b - a + 1))
		end
	end)

	forEachChunk(created, function(a, b)
		local changes = {}
		for k = a, b do
			local p = created[k]
			local d = partData[p]
			changes[#changes + 1] = {
				Part = p,
				Transparency = d.t,
				Reflectance = d.r,
			}
		end
		local ok = f3x("SyncMaterial", changes)
		if not ok then
			materialFailures = materialFailures + ((b - a + 1))
		end
	end)

	forEachChunk(created, function(a, b)
		local changes = {}
		for k = a, b do
			local p = created[k]
			local d = partData[p]
			changes[#changes + 1] = { Part = p, Anchored = d.a }
		end
		local ok = f3x("SyncAnchor", changes)
		if not ok then
			anchorFailures = anchorFailures + ((b - a + 1))
		end
	end)

	forEachChunk(created, function(a, b)
		local changes = {}
		for k = a, b do
			local p = created[k]
			local d = partData[p]
			changes[#changes + 1] = { Part = p, CanCollide = d.cc }
		end
		local ok = f3x("SyncCollision", changes)
		if not ok then
			collisionFailures = collisionFailures + ((b - a + 1))
		end
	end)

	if CONFIG.applyNames then
		forEachChunk(created, function(a, b)
			local items, names = {}, {}
			for k = a, b do
				local p = created[k]
				items[#items + 1] = p
				names[#names + 1] = partData[p].n
			end
			local ok = f3x("SetName", items, names)
			if not ok then
				nameFailures = nameFailures + ((b - a + 1))
			end
		end)
	end

	
	local groups = {}
	local groupCount = 0
	local renameFailures = 0
	local childrenOf = {}
	for _, m in ipairs(MODELS) do
		if m.p ~= 0 then
			local list = childrenOf[m.p]
			if not list then
				list = {}
				childrenOf[m.p] = list
			end
			list[#list + 1] = m.id
		end
	end

	local function appendModelItems(modelId, out)
		for _, p in ipairs(byModel[modelId] or {}) do
			out[#out + 1] = p
		end
		for _, childId in ipairs(childrenOf[modelId] or {}) do
			local g = groups[childId]
			if g then
				out[#out + 1] = g
			else
				appendModelItems(childId, out)
			end
		end
	end

	local groupFailures = 0
	for _, m in ipairs(MODELS) do
		local items = {}
		for _, p in ipairs(byModel[m.id] or {}) do
			items[#items + 1] = p
		end
		for _, childId in ipairs(childrenOf[m.id] or {}) do
			local g = groups[childId]
			if g then
				items[#items + 1] = g
			else
				appendModelItems(childId, items)
			end
		end

		local ok, group = f3x("CreateGroup", "Model", workspace, items)
		if ok and typeof(group) == "Instance" and group:IsA("Model") then
			groups[m.id] = group
			groupCount = groupCount + (1)
			local renamed = f3x("SetName", {group}, m.n)
			if not renamed then
				renameFailures = renameFailures + (1)
			end
		else
			groupFailures = groupFailures + (1)
			if groupFailures <= 10 then
				warn(("CreateGroup failed for source model %d (%s)"):format(m.id, m.n))
			end
		end
		task.wait(CONFIG.groupDelay)
	end

	local rootGroup = groups[1]
	if rootGroup then
		print(("Model tree built under: %s"):format(rootGroup:GetFullName()))
	else
		warn("Root Geometry group was not created; parts remain in Workspace.")
	end

	if CONFIG.applyModelPivots then
		local changes = {}
		for _, m in ipairs(MODELS) do
			local g = groups[m.id]
			if g then
				changes[#changes + 1] = { Model = g, Pivot = makeCFrame(m.pv) }
			end
		end
		forEachChunk(changes, function(a, b)
			local chunk = {}
			for k = a, b do
				chunk[#chunk + 1] = changes[k]
			end
			f3x("SyncMove", chunk)
		end)
	end

	local decalsCreated = 0
	if CONFIG.createDecals then
		for _, d in ipairs(DECALS) do
			local p = createdById[d.part]
			if p then
				local ok, textures = f3x("CreateTextures", {
					{ Part = p, TextureType = "Decal", Face = Enum.NormalId.Front },
				})
				if ok and type(textures) == "table" and #textures > 0 then
					local synced = f3x("SyncTexture", {
						{
							Part = p,
							TextureType = "Decal",
							Face = Enum.NormalId.Front,
							Texture = d.texture,
							Transparency = d.transparency,
						},
					})
					if synced then
						decalsCreated = decalsCreated + (1)
					end
				else
					warn(("CreateTextures failed for source part %d"):format(d.part))
				end
				task.wait(CONFIG.groupDelay)
			end
		end
	end


	task.wait(CONFIG.verifyAfterSeconds)

	local mismatches = { size = 0, color = 0, material = 0, anchor = 0, collision = 0, name = 0 }
	for _, p in ipairs(created) do
		local d = partData[p]
		if (p.Size - Vector3.new(table.unpack(d.s))).Magnitude > 0.01 then
			mismatches.size = mismatches.size + (1)
		end
		local expectedColor = Color3.new(table.unpack(d.c))
		if math.abs(p.Color.R - expectedColor.R) > 0.01
			or math.abs(p.Color.G - expectedColor.G) > 0.01
			or math.abs(p.Color.B - expectedColor.B) > 0.01 then
			mismatches.color = mismatches.color + (1)
		end
		if math.abs(p.Transparency - d.t) > 0.01 or math.abs(p.Reflectance - d.r) > 0.01 then
			mismatches.material = mismatches.material + (1)
		end
		if p.Anchored ~= d.a then
			mismatches.anchor = mismatches.anchor + (1)
		end
		if p.CanCollide ~= d.cc then
			mismatches.collision = mismatches.collision + (1)
		end
		if CONFIG.applyNames and p.Name ~= d.n then
			mismatches.name = mismatches.name + (1)
		end
	end

	print("---------------- F3X build report ----------------")
	print(("Parts created:        %d / %d (create failures: %d)"):format(#created, partLimit, createFailures))
	print(("Groups created:       %d / %d (group failures: %d, rename failures: %d)"):format(groupCount, #MODELS, groupFailures, renameFailures))
	print(("Decals recreated:     %d / %d"):format(decalsCreated, #DECALS))
	local groupNameMismatches, groupParentMismatches = 0, 0
	for _, m in ipairs(MODELS) do
		local g = groups[m.id]
		if g then
			if g.Name ~= m.n then
				groupNameMismatches = groupNameMismatches + (1)
			end
			local expectedParent = (m.p == 0) and workspace or groups[m.p]
			if expectedParent and g.Parent ~= expectedParent then
				groupParentMismatches = groupParentMismatches + (1)
			end
		end
	end

	print(("Invoke exceptions:    resize=%d color=%d material=%d anchor=%d collision=%d name=%d"):format(resizeFailures, colorFailures, materialFailures, anchorFailures, collisionFailures, nameFailures))
	print(("State mismatches:     size=%d color=%d material=%d anchor=%d collision=%d name=%d"):format(mismatches.size, mismatches.color, mismatches.material, mismatches.anchor, mismatches.collision, mismatches.name))
	print(("Group mismatches:     name=%d parent=%d"):format(groupNameMismatches, groupParentMismatches))
	print("Snaps, welds and legacy body movers were not recreated: all source parts are anchored, so the exported geometry is static.")
	if mismatches.size + mismatches.color + mismatches.material + mismatches.anchor + mismatches.collision + mismatches.name > 0 then
		warn("Some server-side changes did not replicate. Check build permissions, private building areas, and whether this is the standard F3X tool.")
	else
		print("All verified part properties match the source data.")
	end
end

main()
